{
  "title": "Plan para presentarse en inglés con confianza",
  "description": "Ruta de aprendizaje para pasar de principiante a una presentación oral de dos minutos sin apuntes, ajustada a tu disponibilidad semanal.",
  "outcome": "Presentación oral de dos minutos en inglés sin usar notas",
  "category": "learning",
  "first_action": "Escribir un borrador inicial de la presentación personal de dos minutos en inglés.",
  "summary": "Acciones diarias cortas para memorizar frases clave, practicar lectura en voz alta y grabar sesiones semanales de autoevaluación.",
  "milestones": [
    {
      "title": "Borrador inicial",
      "tasks": [
        {
          "title": "Escribir borrador de presentación (2 min)",
          "description": "Redactar el texto base de la presentación personal en inglés.",
          "priority": "high",
          "minutes": 30,
          "day_offset": 0,
          "deadline": null
        }
      ]
    },
    {
      "title": "Práctica de lectura y grabación",
      "tasks": [
        {
          "title": "Leer el borrador en voz alta (1 min)",
          "description": "Leer el texto escrito dos veces seguidas para ganar fluidez.",
          "priority": "medium",
          "minutes": 30,
          "day_offset": 2,
          "deadline": null
        },
        {
          "title": "Grabar la primera prueba (2 min)",
          "description": "Grabarse leyendo el borrador y escuchar los errores.",
          "priority": "medium",
          "minutes": 30,
          "day_offset": 4,
          "deadline": null
        }
      ]
    },
    {
      "title": "Refinamiento del guion",
      "tasks": [
        {
          "title": "Corregir y simplificar el texto (1 min)",
          "description": "Eliminar palabras complejas para facilitar la memorización.",
          "priority": "high",
          "minutes": 30,
          "day_offset": 6,
          "deadline": null
        },
        {
          "title": "Memorizar el inicio y final (1 min)",
          "description": "Repasar solo la introducción y conclusión hasta memorizarlas.",
          "priority": "medium",
          "minutes": 30,
          "day_offset": 8,
          "deadline": null
        }
      ]
    },
    {
      "title": "Práctica sin apuntes parcial",
      "tasks": [
        {
          "title": "Presentar solo la mitad del texto (1 min)",
          "description": "Intentar decir la primera mitad sin mirar el papel.",
          "priority": "medium",
          "minutes": 30,
          "day_offset": 10,
          "deadline": null
        },
        {
          "title": "Presentar solo la segunda mitad (1 min)",
          "description": "Intentar decir la segunda mitad sin mirar el papel.",
          "priority": "medium",
          "minutes": 30,
          "day_offset": 12,
          "deadline": null
        }
      ]
    },
    {
      "title": "Integración total",
      "tasks": [
        {
          "title": "Presentar todo el texto sin apuntes (2 min)",
          "description": "Realizar la presentación completa desde el inicio hasta el final.",
          "priority": "high",
          "minutes": 30,
          "day_offset": 14,
          "deadline": null
        },
        {
          "title": "Grabar y revisar la versión final (2 min)",
          "description": "Grabar la presentación completa y analizar la fluidez.",
          "priority": "medium",
          "minutes": 30,
          "day_offset": 16,
          "deadline": null
        }
      ]
    },
    {
      "title": "Consolidación de confianza",
      "tasks": [
        {
          "title": "Repasar puntos débiles detectados (1 min)",
          "description": "Enfocar la práctica en las frases donde se duda más.",
          "priority": "medium",
          "minutes": 30,
          "day_offset": 18,
          "deadline": null
        },
        {
          "title": "Simulación final con grabación (2 min)",
          "description": "Hacer la presentación final ante una cámara o espejo.",
          "priority": "high",
          "minutes": 30,
          "day_offset": 20,
          "deadline": null
        }
      ]
    },
    {
      "title": "Evaluación de logro",
      "tasks": [
        {
          "title": "Comparar grabación inicial con final (1 min)",
          "description": "Escuchar ambas versiones para notar la mejora en confianza.",
          "priority": "low",
          "minutes": 30,
          "day_offset": 22,
          "deadline": null
        },
        {
          "title": "Celebrar el logro y planificar uso real (1 min)",
          "description": "Reconocer la meta alcanzada y pensar en dónde usarla.",
          "priority": "low",
          "minutes": 30,
          "day_offset": 24,
          "deadline": null
        }
      ]
    }
  ]
}

{
  "title": "Práctica de inglés con presentaciones cortas",
  "description": "Plan para responder tres preguntas en inglés usando grabaciones breves, aprovechando los días disponibles.",
  "outcome": "Responder tres preguntas sobre mí en inglés oral o escrito",
  "category": "learning",
  "first_action": "Revisar las respuestas a las tres preguntas clave y preparar el guion en inglés (15 min)",
