          "minutes": 5,
          "day_offset": 1,
          "deadline": null
        }
      ]
    },
    {
      "title": "Repaso de vocabulario",
      "tasks": [
        {
          "title": "Revisar palabras nuevas usadas en la grabación",
          "description": "Anotar 5 términos difíciles y buscar su significado.",
          "priority": "medium",
          "minutes": 10,
          "day_offset": 3,
          "deadline": null
        }
      ]
    },
    {
      "title": "Segunda grabación",
      "tasks": [
        {
          "title": "Grabar la segunda respuesta en inglés",
          "description": "Leer el guion preparado y guardar el audio.",
          "priority": "high",
          "minutes": 10,
          "day_offset": 5,
          "deadline": null
        },
        {
          "title": "Enviar la segunda grabación",
          "description": "Compartir el archivo y confirmar recepción.",
          "priority": "medium",
          "minutes": 5,
          "day_offset": 5,
          "deadline": null
        }
      ]
    },
    {
      "title": "Tercera grabación final",
      "tasks": [
        {
          "title": "Grabar la tercera respuesta en inglés",
          "description": "Leer el guion y guardar el audio final.",
          "priority": "high",
          "minutes": 10,
          "day_offset": 7,
          "deadline": null
        },
        {
          "title": "Enviar la tercera grabación",
          "description": "Subir el archivo y cerrar la tarea principal.",
          "priority": "medium",
          "minutes": 5,
          "day_offset": 7,
          "deadline": null
        }
      ]
    }
  ]
}

{
