          "priority": "medium",
          "minutes": 20,
          "day_offset": 12,
          "deadline": null
        }
      ]
    },
    {
      "title": "Dibujo final de la taza",
      "tasks": [
        {
          "title": "Completar el dibujo de la taza.",
          "description": "Finalizar todos los detalles para obtener el resultado observable.",
          "priority": "high",
          "minutes": 20,
          "day_offset": 14,
          "deadline": null
        }
      ]
    }
  ]
}

{
  "title": "Presentación en inglés: Primeros pasos",
  "description": "Planificación para construir confianza y practicar la presentación de dos minutos sin apuntes.",
  "outcome": "Realizar una presentación de dos minutos en inglés frente a un espejo o grabada, con estructura clara y sin notas.",
  "category": "learning",
  "first_action": "Escribir el guion de la presentación de dos minutos en papel para visualizarlo antes de hablar.",
  "summary": "Se establecen cuatro semanas de práctica progresiva, priorizando la escritura del guion y la repetición diaria. Se respetan los días disponibles (lunes, miércoles, viernes) y los límites de tiempo diarios y semanales.",
  "milestones": [
    {
      "title": "Escribir el guion",
      "tasks": [
        {
          "title": "Escribir el guion de la presentación en papel",
          "description": "Redactar los puntos clave para hablar dos minutos sin apuntes.",
          "priority": "high",
          "minutes": 30,
          "day_offset": 0,
          "deadline": null
        }
      ]
    },
    {
      "title": "Práctica guiada y grabación",
      "tasks": [
        {
          "title": "Leer el guion en voz alta tres veces",
          "description": "Familiarizarse con el texto sin mirar las palabras.",
          "priority": "high",
          "minutes": 30,
          "day_offset": 1,
          "deadline": null
        },
        {
          "title": "Grabar la primera presentación de dos minutos",
          "description": "Presentarse frente al espejo sin mirar el papel.",
          "priority": "high",
          "minutes": 30,
          "day_offset": 2,
          "deadline": null
        },
        {
          "title": "Revisar la grabación y corregir errores básicos",
          "description": "Identificar dónde se perdió el hilo o se olvidó algo.",
          "priority": "medium",
          "minutes": 30,
          "day_offset": 3,
          "deadline": null
        }
      ]
    },
    {
      "title": "Refinamiento y fluidez",
      "tasks": [
        {
          "title": "Practicar sin leer el guion durante dos minutos",
          "description": "Intentar recordar la estructura mientras se habla.",
          "priority": "high",
          "minutes": 30,
          "day_offset": 4,
          "deadline": null
        },
        {
          "title": "Grabar una versión mejorada y comparar con la anterior",
          "description": "Notar mejoras en la fluidez y confianza.",
          "priority": "medium",
          "minutes": 30,
          "day_offset": 5,
          "deadline": null
        },
        {
          "title": "Ensayar con un compañero o grabación de voz",
          "description": "Simular la presión de una audiencia real.",
          "priority": "medium",
          "minutes": 30,
          "day_offset": 6,
          "deadline": null
        }
      ]
    },
    {
      "title": "Consolidación y presentación final",
      "tasks": [
        {
          "title": "Presentar sin apuntes frente a un espejo durante dos minutos",
          "description": "Ejecución final de la habilidad objetivo.",
          "priority": "high",
          "minutes": 30,
          "day_offset": 7,
          "deadline": null
        },
        {
          "title": "Reflexionar sobre lo aprendido y definir próximos pasos",
          "description": "Escribir brevemente qué se mejoró esta semana.",
          "priority": "low",
          "minutes": 30,
          "day_offset": 8,
          "deadline": null
        }
      ]
    }
  ]
}

{
  "title": "Plan para presentarse en inglés con confianza",
  "description": "Ruta de aprendizaje para pasar de principiante a una presentación oral de dos minutos sin apuntes.",
