          "priority": "high",
          "minutes": 30,
          "day_offset": 10,
          "deadline": null
        },
        {
          "title": "Revisar grabación y ajustar ritmo",
          "description": "Corregir errores de pronunciación detectados.",
          "priority": "medium",
          "minutes": 30,
          "day_offset": 12,
          "deadline": null
        }
      ]
    }
  ]
}

