{
  "category": "learning",
  "description": "Practicar inglés con menos tiempo, usando momentos cortos y fáciles de integrar en el día.",
  "first_action": "Escuchar un audio de 3 minutos sobre temas personales (ej. trabajo, familia) en inglés, sin traducir.",
  "milestones": [
    {
      "tasks": [
        {
          "day_offset": 0,
          "deadline": "2026-10-12",
          "description": "Escuchar un audio de 3 minutos sobre temas personales en inglés.",
          "minutes": 3,
          "priority": "high",
          "title": "Escuchar audio breve"
        },
        {
          "day_offset": 1,
          "deadline": "2026-10-13",
          "description": "Repetir en voz alta un fragmento de 1 minuto del audio, con pausas naturales.",
          "minutes": 1,
          "priority": "medium",
          "title": "Repetir fragmento"
        },
        {
          "day_offset": 2,
          "deadline": "2026-10-14",
          "description": "Responder una pregunta en inglés sobre su vida (ej. ¿Qué haces en el fin de semana?) en 1 minuto.",
          "minutes": 1,
          "priority": "medium",
          "title": "Responder pregunta"
        },
        {
          "day_offset": 3,
          "deadline": "2026-10-15",
          "description": "Grabar un mensaje de 30 segundos diciendo qué hizo hoy en inglés.",
          "minutes": 30,
          "priority": "high",
          "title": "Grabar mensaje diario"
        }
      ],
      "title": "Primer paso: escuchar y hablar brevemente en inglés cada día útil"
    },
    {
